import os,subprocess
E={**os.environ,'AGENT_BROWSER_SESSION':'pln-c5-final'}
def run(*args):subprocess.run(['proofshot','exec',*args],env=E,check=True)
wait='document.getElementById("form").requestSubmit();for(let n=0;n<300&&document.getElementById("run").disabled;n++)await new Promise(r=>setTimeout(r,100));'
run('eval','''(async()=>{document.getElementById("model").value="C5-full";document.getElementById("fen").value="7k/8/8/1pP5/8/8/8/2K5 w - b6 0 2";document.getElementById("move").value="c5b6";document.getElementById("temporal-mode").value="trusted-metadata";document.getElementById("history").value=JSON.stringify({source:"test-metadata",confidence:.8});'''+wait+'''const d=JSON.parse(document.getElementById("raw").textContent);if(d.temporal_evidence.mode!=="trusted-metadata"||d.temporal_evidence.ep_truth_value.confidence!==.8)throw Error("Trust mode mismatch");document.getElementById("temporal").parentElement.open=true;document.getElementById("temporal").scrollIntoView();return {mode:d.temporal_evidence.mode,status:d.temporal_evidence.status,tv:d.temporal_evidence.ep_truth_value};})()''')
run('screenshot','trusted-temporal-metadata.png')
run('eval','''(async()=>{document.getElementById("temporal-mode").value="event-backed";document.getElementById("history").value=JSON.stringify({source:"test-events",confidence:.99,initial_fen:"7k/1p6/8/2P5/8/8/8/2K5 b - - 0 1",moves:["b7b5"]});'''+wait+'''const d=JSON.parse(document.getElementById("raw").textContent);if(!d.candidate.observations.complete||d.temporal_evidence.status!=="structurally-consistent")throw Error("Event scope failure");document.getElementById("temporal").scrollIntoView();return {events:d.temporal_evidence.events.length,ep:d.temporal_evidence.ep_truth_value,castle:d.temporal_evidence.castle_truth_value,classification:d.candidate.classification};})()''')
run('screenshot','event-backed-ep-scope.png')
run('eval','''(async()=>{document.getElementById("temporal-mode").value="fen-only";document.getElementById("history").value="{}";document.getElementById("fen").value="2bk3K/8/5N2/7n/8/2B5/8/8 w - - 0 1";document.getElementById("move").value="f6h5";document.getElementById("max-invocations").value="0";'''+wait+'''const d=JSON.parse(document.getElementById("raw").textContent);if(d.candidate.classification!=="incomplete"||!d.truncated)throw Error("Budget hidden");document.getElementById("title").scrollIntoView();return {classification:d.candidate.classification,truncated:d.truncated};})()''')
run('screenshot','incomplete-proof-budget.png')
run('eval','''(async()=>{document.getElementById("fen").value="malformed";'''+wait+'''if(current!==null||document.getElementById("raw").textContent!=="")throw Error("Stale export after bad input");document.getElementById("status").scrollIntoView();return {status:document.getElementById("status").textContent,exportCleared:current===null};})()''')
run('screenshot','invalid-input-clears-results.png')
run('eval','''(async()=>{document.getElementById("fen").value="2bk3K/8/5N2/7n/8/2B5/8/8 w - - 0 1";document.getElementById("max-invocations").value="20000";const original=window.fetch;window.fetch=async()=>new Response(JSON.stringify({error:"Native runtime unavailable (verification harness)"}),{status:503,headers:{"Content-Type":"application/json"}});try{'''+wait+'''if(current!==null||!document.getElementById("status").textContent.includes("Native runtime unavailable"))throw Error("Runtime error hidden");return {status:document.getElementById("status").textContent};}finally{window.fetch=original;}})()''')
run('screenshot','native-runtime-error-contract.png')
run('set','viewport','390','844')
run('eval','''(async()=>{'''+wait+'''if(document.documentElement.scrollWidth>innerWidth)throw Error("Mobile horizontal overflow");const original=URL.createObjectURL;let blob;URL.createObjectURL=b=>{blob=b;return original(b)};document.getElementById("export-diagnostic").click();URL.createObjectURL=original;const exported=JSON.parse(await blob.text());if(exported.schema!==5||!exported.candidate.proof_plan)throw Error("Wrong export");document.getElementById("title").scrollIntoView();return {width:innerWidth,scroll:document.documentElement.scrollWidth,exportSchema:exported.schema};})()''')
run('screenshot','mobile-proof-gap-and-export.png')
subprocess.run(['proofshot','stop'],env=E,check=True)
subprocess.run(['agent-browser','close'],env=E,check=False)
